package dk.jamesbabz.madkursus.inbound.rest.mealplan;
import java.net.URI; import java.math.BigDecimal; import java.util.*; import dk.jamesbabz.madkursus.inbound.rest.MealPlanApiDelegate; import dk.jamesbabz.madkursus.inbound.rest.dto.*; import dk.jamesbabz.madkursus.inbound.rest.recipe.RecipeRestMapper; import dk.jamesbabz.madkursus.service.applications.MealPlanService; import dk.jamesbabz.madkursus.service.models.*; import lombok.RequiredArgsConstructor; import org.springframework.http.ResponseEntity; import org.springframework.stereotype.Component;
@Component @RequiredArgsConstructor public class MealPlanApiDelegateImpl implements MealPlanApiDelegate { private final MealPlanService service; private final MealPlanRestMapper mapper; private final RecipeRestMapper recipeMapper;
 public ResponseEntity<List<MealPlanDTO>> getMealPlans(){return ResponseEntity.ok(service.getAll().stream().map(mapper::toDto).toList());} public ResponseEntity<MealPlanDTO> getMealPlan(UUID id){return ResponseEntity.ok(mapper.toDto(service.get(id)));}
 public ResponseEntity<MealPlanDTO> createMealPlan(CreateMealPlanDTO r){MealPlanDTO result=mapper.toDto(service.create(r.getName(),r.getRecipes().stream().map(x->new RecipeSelection(x.getRecipeId(),x.getPortions())).toList()));return ResponseEntity.created(URI.create("/v1/meal-plans/"+result.getId())).body(result);} public ResponseEntity<MealPlanDTO> updateMealPlan(UUID id,UpdateMealPlanDTO r){return ResponseEntity.ok(mapper.toDto(service.rename(id,r.getName())));} public ResponseEntity<Void> deleteMealPlan(UUID id){service.delete(id);return ResponseEntity.noContent().build();}
 public ResponseEntity<MealPlanDTO> addPlannedRecipe(UUID id,CreatePlannedRecipeDTO r){return ResponseEntity.ok(mapper.toDto(service.addRecipe(id,r.getRecipeId(),r.getPortions())));} public ResponseEntity<MealPlanDTO> updatePlannedRecipe(UUID id,UUID plannedId,UpdatePlannedRecipeDTO r){return ResponseEntity.ok(mapper.toDto(service.updateRecipe(id,plannedId,r.getPortions(),r.getSortOrder())));} public ResponseEntity<MealPlanDTO> deletePlannedRecipe(UUID id,UUID plannedId){return ResponseEntity.ok(mapper.toDto(service.removeRecipe(id,plannedId)));}
 public ResponseEntity<CookRecipeResultDTO> cookPlannedRecipe(UUID id,UUID plannedId){return ResponseEntity.ok(recipeMapper.toDto(service.cook(id,plannedId)));} public ResponseEntity<MealPlanDTO> toggleSkipPlannedRecipe(UUID id,UUID plannedId){return ResponseEntity.ok(mapper.toDto(service.skip(id,plannedId)));} public ResponseEntity<RecipeRequirementCalculationDTO> getMealPlanRequirements(UUID id){return ResponseEntity.ok(recipeMapper.toDto(service.requirements(id)));} public ResponseEntity<RecipeRequirementCalculationDTO> addMealPlanMissingToShoppingList(UUID id){return ResponseEntity.ok(recipeMapper.toDto(service.addMissing(id)));}
}
